def _merge_params(base: Dict[str, Any], extra: Dict[str, Any]) -> Dict[str, Any]:
    merged = dict(base or {})
    for k, v in (extra or {}).items():
        if v is not None:
            merged[k] = v
    return merged


def _send_with_retries(
    api_client,
    endpoint: str,
    params: Dict[str, Any],
    headers: Dict[str, str],
    attempts: int,
    delay: float,
):
    """
    Simple retry loop for transient failures/timeouts.
    """
    last_exc = None
    for attempt in range(1, attempts + 1):
        try:
            return api_client.get(endpoint=endpoint, headers=headers, params=params)
        except Exception as exc:  # Network errors, timeouts, etc.
            last_exc = exc
            if attempt >= attempts:
                raise
            time.sleep(delay)
    if last_exc:
        raise last_exc


