@pytest.mark.parametrize("row", argvalues=lambda test_data: test_data, indirect=False)
def test_ip_lookup_table_driven_validations(
    row: Dict[str, Any],
    api_client,
    endpoints: Dict[str, str],
    auth_context: Dict[str, Dict[str, str]],
    request_schema: Dict[str, Any],
    response_schemas: Dict[str, Dict[str, Any]],
    spec_validator: SwaggerSchemaValidator,
    retry_config: Tuple[int, float],
    require_auth_or_skip,
):
    """
    Table-driven test that:
    - Validates request params using SwaggerSchemaValidator before sending
    - Sends GET /v1/ip.json with config-driven auth
    - Asserts expected status code from test data
    - Validates response body using appropriate schema via SwaggerSchemaValidator

    Each iteration uses one JSON object from ip_json.json.
    Authentication-specific tests are handled separately and thus are skipped if no key is configured.
    """
    # Build request params from test data + auth params; no hardcoded payloads.
    q_value = row.get("q")
    expected_status = int(row.get("statusCode"))
    attempts, delay = retry_config

    # Prepare params and headers
    base_params = {"q": q_value}
    params = _merge_params(base_params, auth_context.get("params"))
    headers = dict(auth_context.get("headers", {}))

    # Request validation before sending
    spec_validator.validate_with_schema(params, request_schema)

    # Send request (with retries)
    response = _send_with_retries(
        api_client=api_client,
        endpoint=endpoints["ip_lookup"],
        params=params,
        headers=headers,
        attempts=attempts,
        delay=delay,
    )

    # Status code assertion from test data
    assert response.status_code == expected_status, (
        f"Unexpected status for q='{q_value}'. "
        f"Expected {expected_status}, got {response.status_code}. Body: {response.text}"
    )

    # Parse response JSON (required for schema validation)
    # Note: We avoid custom validation; parsing is necessary to feed the validator.
    try:
        body = response.json()
    except Exception as exc:
        pytest.fail(f"Response is not valid JSON for q='{q_value}': {exc}\nRaw: {response.text}")

    # Response validation after API call using schemas
    status_key = str(expected_status)
    if status_key in response_schemas:
        spec_validator.validate_with_schema(body, response_schemas[status_key])
    else:
        # If a status not in spec occurs, still ensure we can validate against a generic object schema.
        generic_schema = {"type": "object"}
        spec_validator.validate_with_schema(body, generic_schema)


